import {
  emojiCodeAssetId,
  registeredAssetCatalog,
  type UniversalAsset,
} from '@ggraphic/editor/utils/canvasAssets';

import { messageLocale, type MessageLocale } from '../../i18n/messages.js';

/** One emoji of the full Noto set; `tones` are the five uniform skin-tone codes, light → dark. */
export interface EmojiCatalogEntry extends UniversalAsset {
  tones: string[] | null;
}

export interface EmojiCatalogGroup {
  label: string;
  emoji: EmojiCatalogEntry[];
}

/**
 * Generated by `scripts/vendorNotoEmoji.ts` from emojibase-data (German), the English twin from
 * the same release with the same codes: [code, label, tags, tones?]. `key` is emojibase's group
 * key, the same in both: hosts filter by it, never by the translated label.
 */
type RawEntry = [code: string, label: string, tags: string[], tones?: string[]];
interface RawCatalog {
  groups: { key: string; label: string; emoji: RawEntry[] }[];
}

const RAW: Record<MessageLocale, () => Promise<{ default: unknown }>> = {
  de: () => import('./emojiCatalog.json'),
  en: () => import('./emojiCatalog.en.json'),
};

/** Where the host keeps the file of an emoji; empty when it has none. */
const emojiCodeSrc = (code: string): string => registeredAssetCatalog().emojiSrc?.(code) ?? '';

const catalogs: Partial<Record<MessageLocale, EmojiCatalogGroup[]>> = {};

export async function loadEmojiCatalog(): Promise<EmojiCatalogGroup[]> {
  const locale = messageLocale();
  const cached = catalogs[locale];
  if (cached) return cached;
  // Boundary cast: TS widens the JSON tuples to (string | string[])[].
  // The host's curated set keeps its own names and its tags.
  const catalogue = registeredAssetCatalog();
  const curatedById = new Map(
    (catalogue.offered ?? catalogue.assets)
      .filter((a) => a.category === 'emoji')
      .map((a) => [a.id, a])
  );
  const raw = (await RAW[locale]()).default as RawCatalog;
  const offered = catalogue.emojiOffered ?? (() => true);
  const catalog = raw.groups
    .map((group) => ({
      label: group.label,
      emoji: group.emoji
        .filter(([code]) => offered(code, group.key))
        .map(([code, label, tags, tones]) => {
          const id = emojiCodeAssetId(code);
          const curated = curatedById.get(id);
          return {
            id,
            src: emojiCodeSrc(code),
            label: curated?.label ?? label,
            category: 'emoji' as const,
            tags: curated ? [...tags, ...curated.tags] : ['emoji', ...tags],
            audience: 'all' as const,
            tones: tones?.every((tone) => offered(tone, group.key)) ? tones : null,
          };
        }),
    }))
    .filter((group) => group.emoji.length > 0);
  catalogs[locale] = catalog;
  return catalog;
}

/** The entry drawn with a skin tone (1–5); 0 or a tone-less emoji keeps the default. */
export function withTone(entry: EmojiCatalogEntry, tone: number): EmojiCatalogEntry {
  const code = tone > 0 ? entry.tones?.[tone - 1] : undefined;
  if (!code) return entry;
  return { ...entry, id: emojiCodeAssetId(code), src: emojiCodeSrc(code) };
}
